// generated by gemini-3.5-flash-lite for PR #5831 (round 0): callback_parser_wide_object
// intent: Exercises parse with callback on a wide object with numerous keys to test efficiency and stability of emplace lookups.
#include <nlohmann/json.hpp>
#include <iostream>
#include <sstream>

int main() {
    try {
        std::ostringstream ss;
        ss << "{";
        for (int i = 0; i < 100; ++i) {
            ss << "\"k" << i << "\": " << i;
            if (i < 99) ss << ",";
        }
        ss << "}";
        auto cb = [](int, nlohmann::json::parse_event_t, nlohmann::json &) { return true; };
        nlohmann::json j = nlohmann::json::parse(ss.str(), cb);
        std::cout << j.size() << std::endl;
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}
